urlset:
{% for section, sitemap in sitemaps.items %}
    {% for url in sitemap.get_urls %}

            {{ url.location }}
            {% if url.lastmod %}{{ url.lastmod|date:"Y-m-d" }}{% endif %}
            {% if url.changefreq %}{{ url.changefreq }}{% endif %}
            {% if url.priority %}{{ url.priority }}{% endif %}

    {% endfor %}
{% endfor %}
